//! The simulation.
//!
//! The tick order below is part of the specification, not an implementation
//! detail. Reordering any two phases changes results and therefore invalidates
//! every recorded replay — treat it the way you would treat a wire format.
//!
//! `commands → aging → movement → collisions → feeding → settle → terrain →
//! reap` — `feeding` (S2, `phase_feeding`) runs after collisions so predator
//! and prey are compared at this tick's settled positions, and before settle
//! so a kill's `OnDeath` demand and a meal's `OnConsume` demand both land in
//! the same terrain tick's settlement as everything else that happened this
//! tick. `terrain` (S1) runs the six fixed-order operators described in
//! `docs/S1_TERRAIN_DESIGN.md` and `terrain.rs`'s own doc comment.

use crate::climate::{Climate, ClimateTuning};
use crate::ecology::EcologyTuning;
use crate::element::{Element, PerElement};
use crate::entity::{Entity, ACTION_THRESHOLD, MAX_HP};
use crate::fx::{Fx, V2};
use crate::governor::{Governor, Grant};
use crate::hash::{Hashable, Hasher};
use crate::input::{CmdKind, Command, InputLog};
use crate::race::{attrs, Channel as DepChannel, RaceAttrs, MILLI, RACES, TERRAIN_PERIOD};
use crate::rand::{rand_signed, Channel};
use crate::terrain::{Occupancy, Terrain, TerrainTuning};

/// Per-tick positional noise, so entities do not travel on perfect rails.
pub const JITTER: Fx = Fx::ratio(1, 400);

/// Positional spread for an offspring spawned by `phase_feeding`, so a
/// cohort born from the same parent does not stack exactly on top of it.
pub const BIRTH_SCATTER: Fx = Fx::ratio(150, 100);

#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub struct Stats {
    pub births: u64,
    pub deaths: u64,
    pub collisions: u64,
    pub actions: u64,
    /// Total demand refused by the deposit governors. A rising value means
    /// somebody is pushing on a rate limit.
    pub deposit_clipped: u64,
    /// Total emitted purely to honour a floor. A rising value means a race is
    /// absent or idle and the world is turning over without it.
    pub deposit_forced: u64,
    /// S2: successful predation events, counted at the predator.
    pub feedings: u64,
    /// S2: deaths where hunger had already crossed `starve_after` — a subset
    /// of `deaths`, not an addition to it.
    pub starved: u64,

400	    /// race's deposit/consume mix has carried a nonzero share for since
401	    /// Stage 0, with nothing to fire it until now. A meal that carries a
402	    /// body's `hp` up across `repro_threshold` spawns one offspring through
403	    /// the ordinary `World::spawn` path, so it charges `OnBirth` the same
404	    /// way a command-spawned or seeded body always has. Without the
405	    /// `satiation` gate every predator in reach eats every single tick it
406	    /// can, which empirically collapses every prey population within a few
407	    /// hundred ticks. The shipped `EcologyTuning` defaults are, like
408	    /// `TerrainTuning`'s and `ClimateTuning`'s before them, a first guess
409	    /// for the live tuning loop — a uniform five-way predation ring is a
410	    /// hard balance problem, and nothing here promises the shipped numbers
411	    /// converge to a stable population on their own.
412	    ///
413	    /// Pairwise, same O(n²) shape as `phase_collisions` and for the same
414	    /// reason — correct and fast enough here, and a future uniform-grid
415	    /// broadphase would want to serve both passes at once.
416	    /// `element.rs`'s ring arithmetic guarantees at most one direction of any
417	    /// pair can be a predation match (no element eats its own eater — see
418	    /// `nothing_beats_itself_and_the_two_edges_never_coincide`), so every
419	    /// ordered pair is checked once, in ascending-id order (Invariant IV),
420	    /// for a result that depends on that fixed order and never on how many
421	    /// candidates a body could have fed on.
422	    fn phase_feeding(&mut self) {
423	        let n = self.entities.len();
424	        let ecology = self.ecology;
425	        let races = self.races;
426	
427	        // Two scratch passes, the same shape `phase_collisions` uses for its
428	        // `fix` buffer: decide every outcome first, against a fixed snapshot
429	        // of who is alive, then apply — so which pairs are found never
430	        // depends on the order mutations happened to land in.
431	        let mut eaten = vec![false; n];
432	        let mut fed = vec![false; n];
433	
434	        for i in 0..n {
435	            if !self.entities[i].alive || eaten[i] {
436	                continue;
437	            }
438	            for j in (i + 1)..n {
439	                if !self.entities[j].alive || eaten[j] {
440	                    continue;
441	                }
442	                let a = self.entities[i].element;
443	                let b = self.entities[j].element;
444	                let (pred, prey) = if a.eats() == b {
445	                    (i, j)
446	                } else if b.eats() == a {
447	                    (j, i)
448	                } else {
449	                    continue;
450	                };
451	                if eaten[prey] || fed[pred] {
452	                    continue;
453	                }
454	                // Satiation, not an `hp`-below-max gate: a predator that just
455	                // ate ignores further prey in reach until `hunger` has built
456	                // back up. Gating on `hp < MAX_HP` instead would deadlock the
457	                // whole ring — every body spawns below the cap on purpose
458	                // (`Entity::spawn`), but would still only need one meal to
459	                // top out, after which it stops hunting even though
460	                // `hunger` (ticks since last meal) has reset to zero and
461	                // prey is still plentiful.
462	                let pred_el = self.entities[pred].element;
463	                if self.entities[pred].hunger < ecology.satiation[pred_el] {
464	                    continue;
465	                }
466	                let d = self.entities[prey].pos - self.entities[pred].pos;
467	                let reach = ecology.forage_radius[pred_el];
468	                if d.len_sq() > reach * reach {
469	                    continue;
470	                }
471	                eaten[prey] = true;
472	                fed[pred] = true;
473	            }
474	        }
475	
476	        let mut births: Vec<(Element, V2, u32)> = Vec::new();
477	        for (i, &was_fed) in fed.iter().enumerate() {
478	            if !was_fed {
479	                continue;
480	            }
481	            let el = self.entities[i].element;
482	            let before = self.entities[i].hp;
483	            let after = before.saturating_add(ecology.feed_gain[el]).min(MAX_HP);
484	            self.entities[i].hp = after;
485	            self.entities[i].hunger = 0;
486	            self.stats.feedings += 1;
487	            *self.deposit_demand.get_mut(el) += races[el].deposit_per(DepChannel::OnConsume);
488	            *self.consume_demand.get_mut(el) += races[el].consume_per(DepChannel::OnConsume);
489	
490	            if before < ecology.repro_threshold[el] && after >= ecology.repro_threshold[el] {
491	                births.push((el, self.entities[i].pos, self.entities[i].id));
492	            }
493	        }
494	
495	        for (i, &was_eaten) in eaten.iter().enumerate() {
496	            if was_eaten {
497	                let el = self.entities[i].element;
498	                self.entities[i].alive = false;
499	                self.entities[i].hp = 0;
500	                self.charge_death(el);
501	            }
502	        }
503	
504	        // Newborns join by the normal `spawn` path (ascending id, so the
505	        // sort invariant holds) after every kill and every meal from this
506	        // tick is already resolved — a body born from feeding does not
507	        // itself get to move, collide or eat again until its own next tick.
508	        let (seed, tick) = (self.seed, self.tick);
509	        for (el, pos, parent_id) in births {
510	            let jitter = V2::new(
511	                rand_signed(seed, tick, parent_id, Channel::Forage) * BIRTH_SCATTER,
512	                rand_signed(seed, tick, parent_id.wrapping_add(0x0F0D), Channel::Forage) * BIRTH_SCATTER,
513	            );
514	            self.spawn(el, pos + jitter);
515	        }
516	    }
517	
518	    /// 6 — at a terrain-tick boundary, charge existence and settle every
519	    /// governor. This is the only place demand becomes terrain change.

1	//! S2's exit condition, as a runnable check: feeding, starvation and
2	//! reproduction actually happen under the shipped table, and none of them
3	//! break Invariant VI (every tick reproduces from `(seed, input_log)` alone).
4	//!
5	//! What this file does **not** claim: that the shipped `EcologyTuning`
6	//! defaults keep a five-race predation ring alive indefinitely. They do not
7	//! — a uniform five-way closed ring collapses within a few thousand ticks
8	//! under the shipped numbers, the same way S1's shipped `TerrainTuning`
9	//! defaults were not asserted to produce good-looking succession without a
10	//! live tuning pass (`docs/S1_TERRAIN_DESIGN.md` §9.3). Real per-race
11	//! balance is exactly what `chaos`'s live view exists to find. The tests
12	//! here pin down the mechanism, not the balance.
13	
14	use pentagram::ecology::EcologyTuning;
15	use pentagram::element::{Element, PerElement};
16	use pentagram::fx::Fx;
17	use pentagram::input::InputLog;
18	use pentagram::replay::{build, record, scripted_log, verify};
19	
20	const SEED: u64 = 0xC0FFEE;
21	const SIZE: i32 = 64;
22	const PER_RACE: u32 = 12;
23	
24	/// **The exit condition.** Feeding, starvation and reproduction all fire at
25	/// least once under the shipped table within a bounded run — the `OnConsume`
26	/// channel and `Entity::hp` are no longer dead code, and neither is a birth
27	/// that came from something other than a command or `seed_population`.
28	#[test]
29	fn feeding_starvation_and_reproduction_all_occur_under_the_shipped_table() {
30	    let ticks = 8_000u64;
31	    let mut w = build(SEED, SIZE, PER_RACE);
32	    let log = InputLog::new();
33	    let births_before = w.stats.births;
34	    for _ in 0..ticks {
35	        w.step(&log);
36	    }
37	    assert!(w.stats.feedings > 0, "no predation occurred in {ticks} ticks");
38	    assert!(
39	        w.stats.births > births_before,
40	        "no reproduction occurred beyond the initial seed"
41	    );
42	    // Not every run need starve anyone — a body that keeps eating never
43	    // does — so this is observed rather than asserted.
44	    let _ = w.stats.starved;
45	}
46	
47	/// Ten thousand ticks with S2's phases exercised on every one of them,
48	/// replaying bit-identically — the same exit condition Stage 0 shipped,
49	/// re-run now that `phase_feeding` sits in the tick between `phase_collisions`
50	/// and `phase_settle`.
51	#[test]
52	fn ten_thousand_ticks_replay_bit_identically_with_ecology_active() {
53	    let ticks = 10_000;
54	    let log = scripted_log(0x5EED, ticks, PER_RACE * 5);
55	    let trace = record(SEED, SIZE, PER_RACE, &log, ticks);
56	    assert_eq!(trace.ticks(), ticks as usize);
57	    if let Err(d) = verify(&trace, &log) {
58	        panic!("{d}");
59	    }
60	}
61	
62	/// A retuned ecology table is part of state exactly the way a retuned
63	/// `TerrainTuning` or `ClimateTuning` is: two runs from the same seed and log
64	/// but different `EcologyTuning` must diverge.
65	#[test]
66	fn a_retuned_ecology_changes_the_run() {
67	    let ticks = 2_000u64;
68	    let log = scripted_log(0x9, ticks, PER_RACE * 5);
69	
70	    let a = build(SEED, SIZE, PER_RACE);
71	    let mut b = a.clone();
72	    b.retune_ecology(EcologyTuning {
73	        feed_gain: PerElement::filled(1),
74	        ..EcologyTuning::default()
75	    });
76	
77	    let mut a = a;
78	    for _ in 0..ticks {
79	        a.step(&log);
80	        b.step(&log);
81	    }
82	    assert_ne!(a.state_hash(), b.state_hash());
83	}
84	
85	/// A hand-tuned, forgiving table (long satiation window, cheap reproduction,
86	/// generous starvation grace) keeps at least one race alive for a run far
87	/// longer than any individual body's lifespan — proof the mechanism *can*
88	/// sustain a population, even though the shipped defaults do not promise it.
89	#[test]
90	fn a_forgiving_tuning_sustains_at_least_one_race() {
91	    let ticks = 6_000u64;
92	    let mut w = build(SEED, 96, 60);
93	    w.retune_ecology(EcologyTuning {
94	        forage_radius: PerElement::filled(Fx::ratio(500, 100)),
95	        satiation: PerElement::filled(150),
96	        feed_gain: PerElement::filled(70),
97	        starve_after: PerElement::filled(6_000),
98	        starve_rate: PerElement::filled(1),
99	        repro_threshold: PerElement::filled(60),
100	    });
101	    let log = InputLog::new();
102	    for _ in 0..ticks {
103	        w.step(&log);
104	    }
105	    let pop = w.population();
106	    let alive_races = Element::ALL.iter().filter(|e| pop[**e] > 0).count();
107	    assert!(
108	        alive_races > 0,
109	        "every race collapsed within {ticks} ticks even under a forgiving tuning"
110	    );
111	}
