93	/// A value per element. Used everywhere a per-race quantity is needed, and
94	/// preferred over a map because iteration order is then structural rather
95	/// than incidental — Invariant IV.
96	#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
97	pub struct PerElement<T>(pub [T; Element::COUNT]);
98	
99	impl<T> PerElement<T> {
100	    #[inline]
101	    pub fn get(&self, e: Element) -> &T {
102	        &self.0[e.index()]
103	    }
104	
105	    #[inline]
106	    pub fn get_mut(&mut self, e: Element) -> &mut T {
107	        &mut self.0[e.index()]
108	    }
109	
110	    /// Always yields elements in ring order.
111	    pub fn iter(&self) -> impl Iterator<Item = (Element, &T)> {
112	        Element::ALL.into_iter().zip(self.0.iter())
113	    }
114	}
115	
116	impl<T: Copy> PerElement<T> {
117	    pub fn filled(v: T) -> PerElement<T> {
118	        PerElement([v; Element::COUNT])
119	    }

